import React, {useEffect, useMemo, useState} from 'react';
import {createRoot} from 'react-dom/client';
import {Activity, ArrowLeft, BarChart3, CalendarDays, CheckCircle2, ClipboardList, Download, FileText, HeartPulse, ImagePlus, LayoutDashboard, Plus, Search, Settings, Users, X, AlertCircle, CreditCard, Moon, Sun, Trash2, Eye, Pencil, Clock, IndianRupee} from 'lucide-react';
import jsPDF from 'jspdf';
import './styles.css';

type Xray={before?:string;after?:string};
type Exercise={name:string;frequency:string;duration:string;notes:string};
type PaymentEntry={id:string;amount:number;date:string;note?:string};
type Patient={id:string;name:string;age:number;gender:string;phone:string;email?:string;height?:number;weight?:number;address?:string;emergencyContact?:string;medicalHistory?:string;allergies?:string;visitDate:string;visitHistory?:string[];condition:string;painBefore:number;painAfter?:number;mobilityBefore:string;mobilityAfter?:string;notes:string;diagnosis:string;doctor:string;planMonths:number;followUpDate:string;followUpTime?:string;followUpNotes?:string;xray:Xray;exercises:Exercise[];status:'Active'|'Completed'|'Follow-up';fee?:number;paid?:number;paymentHistory?:PaymentEntry[];paymentStatus?:'Done'|'Pending'|'Partially paid'};
type Expense={id:string;type:string;note:string;amount:number;date:string};

const uid=()=>Math.random().toString(36).slice(2,9);
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const sample:Patient[]=[
 {id:'YC-1001',name:'Aarav Sharma',age:42,gender:'Male',phone:'+91 98765 43210',visitDate:'2026-09-21',condition:'Lower back pain',painBefore:8,painAfter:4,mobilityBefore:'Restricted',mobilityAfter:'Improved',notes:'Pain after prolonged sitting. No neurological red flags reported.',diagnosis:'Lumbar posture-related pain',doctor:'Dr. Pradnesh Naikwade',planMonths:3,followUpDate:'2026-12-21',status:'Active',xray:{},exercises:[{name:'Bhujangasana',frequency:'2x daily',duration:'30 sec x 3',notes:'Gentle range only'},{name:'Setu Bandhasana',frequency:'1x daily',duration:'10 reps',notes:'Controlled movement'},{name:'Marjaryasana-Bitilasana',frequency:'2x daily',duration:'10 reps',notes:'Slow breathing'}]},
 {id:'YC-1002',name:'Sneha Patil',age:35,gender:'Female',phone:'+91 91234 56789',visitDate:'2026-08-28',condition:'Cervical discomfort',painBefore:7,painAfter:2,mobilityBefore:'Restricted',mobilityAfter:'Good',notes:'Improved neck mobility after consistent exercise plan.',diagnosis:'Cervical strain',doctor:'Dr. Pradnesh Naikwade',planMonths:3,followUpDate:'2026-11-28',status:'Follow-up',xray:{},exercises:[{name:'Neck Isometric',frequency:'2x daily',duration:'5 reps',notes:'No pain during exercise'},{name:'Tadasana',frequency:'1x daily',duration:'60 sec',notes:'Posture focus'}]},
 {id:'YC-1003',name:'Rohan Kulkarni',age:51,gender:'Male',phone:'+91 99887 77665',visitDate:'2026-06-10',condition:'Knee pain',painBefore:6,painAfter:1,mobilityBefore:'Moderate',mobilityAfter:'Good',notes:'Functional improvement noted.',diagnosis:'Knee mobility limitation',doctor:'Dr. Rao',planMonths:3,followUpDate:'2026-09-10',status:'Completed',xray:{},exercises:[{name:'Chair-supported squat',frequency:'1x daily',duration:'8 reps',notes:'Use support'},{name:'Vrikshasana',frequency:'1x daily',duration:'30 sec/side',notes:'Balance focus'}]}
];

function load():Patient[]{try{const rows=JSON.parse(localStorage.getItem('yogacare-patients')||'null') as Patient[]|null;return rows?.map(p=>({...p,doctor:p.doctor==='Dr. Meheta'||p.doctor==='Dr. Mehta'?'Dr. Pradnesh Naikwade':p.doctor}))||sample}catch{return sample}}
function App(){
 const [patients,setPatients]=useState<Patient[]>(load); const [expenses,setExpenses]=useState<Expense[]>(()=>{try{return JSON.parse(localStorage.getItem('yogacare-expenses')||'[]')}catch{return []}}); const [page,setPage]=useState<'dashboard'|'patients'|'patient'|'payments'|'outcomes'|'settings'|'followups'>('dashboard'); const [selected,setSelected]=useState<string|null>(null); const [search,setSearch]=useState(''); const [showNew,setShowNew]=useState(false); const [scheduleNew,setScheduleNew]=useState(false); const [theme,setTheme]=useState(localStorage.getItem('yogacare-theme')||'light');
 useEffect(()=>localStorage.setItem('yogacare-patients',JSON.stringify(patients)),[patients]);
 useEffect(()=>localStorage.setItem('yogacare-expenses',JSON.stringify(expenses)),[expenses]);
 const active=patients.find(p=>p.id===selected)||null;
 const openPatient=(id:string)=>{setSelected(id);setPage('patient')};
 const update=(p:Patient)=>setPatients(a=>a.map(x=>x.id===p.id?p:x));
 useEffect(()=>{document.documentElement.dataset.theme=theme;localStorage.setItem('yogacare-theme',theme)},[theme]);
 return <div className="app"><Sidebar page={page} setPage={p=>{setPage(p);if(p!=='patient')setSelected(null)}} onNew={()=>{setScheduleNew(false);setShowNew(true)}}/><main className="main"><Topbar search={search} setSearch={setSearch} onNew={()=>{setScheduleNew(false);setShowNew(true)}} theme={theme} toggleTheme={()=>setTheme(theme==='light'?'dark':'light')}/>{page==='dashboard'&&<Dashboard patients={patients} expenses={expenses} onOpen={openPatient}/>} {page==='patients'&&<Patients patients={patients} search={search} onOpen={openPatient} onNew={()=>setShowNew(true)} update={update} onDelete={id=>setPatients(rows=>rows.filter(p=>p.id!==id))}/>} {page==='followups'&&<FollowUps patients={patients} update={update} onOpen={openPatient} onNew={()=>{setScheduleNew(true);setShowNew(true)}}/>} {page==='patient'&&active&&<PatientDetail patient={active} update={update} back={()=>setPage('patients')}/>} {page==='payments'&&<Payments patients={patients} update={update} expenses={expenses} setExpenses={setExpenses}/>} {page==='outcomes'&&<Reports patients={patients} expenses={expenses}/>} {page==='settings'&&<SettingsPage patients={patients} setPatients={setPatients}/> }</main>{showNew&&<NewPatient scheduleVisit={scheduleNew} onClose={()=>{setShowNew(false);setScheduleNew(false)}} onCreate={p=>{setPatients(a=>[p,...a]);setShowNew(false);setScheduleNew(false);openPatient(p.id)}}/>}</div>
}
function Sidebar({page,setPage,onNew}:{page:string;setPage:(p:any)=>void;onNew:()=>void}){return <aside className="sidebar"><div className="brand"><div className="brandmark"><HeartPulse size={20}/></div><div><b>YogaCare</b><span>Patient CRM</span></div></div><button className="newBtn" onClick={onNew}><Plus size={17}/> New patient</button><nav><Nav icon={<LayoutDashboard/>} label="Dashboard" active={page==='dashboard'} onClick={()=>setPage('dashboard')}/><Nav icon={<Users/>} label="Patients" active={page==='patients'} onClick={()=>setPage('patients')}/><Nav icon={<CreditCard/>} label="Payments" active={page==='payments'} onClick={()=>setPage('payments')}/><Nav icon={<BarChart3/>} label="Reports" active={page==='outcomes'} onClick={()=>setPage('outcomes')}/><Nav icon={<CalendarDays/>} label="Follow-ups" active={page==='followups'} onClick={()=>setPage('followups')}/></nav><div className="sideBottom"><Nav icon={<Settings/>} label="Settings" active={page==='settings'} onClick={()=>setPage('settings')}/><div className="doctor"><div className="avatar">PN</div><div><b>Dr. Pradnesh Naikwade</b><span>Yoga therapist</span></div></div></div></aside>}
function Nav({icon,label,active,onClick}:{icon:React.ReactNode;label:string;active:boolean;onClick:()=>void}){return <button className={'nav '+(active?'active':'')} onClick={onClick}>{icon}<span>{label}</span></button>}
function Topbar({search,setSearch,onNew,theme,toggleTheme}:{search:string;setSearch:(v:string)=>void;onNew:()=>void;theme:string;toggleTheme:()=>void}){const [now,setNow]=useState(new Date());useEffect(()=>{const timer=window.setInterval(()=>setNow(new Date()),60000);return()=>window.clearInterval(timer)},[]);const hour=now.getHours(),greeting=hour<12?'Good morning':hour<17?'Good afternoon':hour<21?'Good evening':'Good night';return <header className="topbar"><div><div className="dateStamp">{now.toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</div><h1>{greeting}, Dr. Pradnesh Naikwade</h1><p>Track patient progress from first visit to follow-up.</p></div><div className="topActions"><div className="search"><Search size={17}/><input placeholder="Search patients..." value={search} onChange={e=>setSearch(e.target.value)}/></div><button className="iconBtn" title="Toggle theme" onClick={toggleTheme}>{theme==='light'?<Moon/>:<Sun/>}</button><button className="iconBtn" title="Add patient" onClick={onNew}><Plus/></button></div></header>}
function Dashboard({patients,expenses,onOpen}:{patients:Patient[];expenses:Expense[];onOpen:(id:string)=>void}){const revenue=patients.reduce((s,p)=>s+(p.paid||0),0),balance=patients.reduce((s,p)=>s+Math.max(0,(p.fee||0)-(p.paid||0)),0),spend=expenses.reduce((s,e)=>s+e.amount,0),recent=[...patients].filter(p=>p.visitDate).sort((a,b)=>b.visitDate.localeCompare(a.visitDate)).slice(0,5),scheduled=patients.filter(p=>p.followUpDate&&p.status!=='Completed').sort((a,b)=>a.followUpDate.localeCompare(b.followUpDate)),upcoming=scheduled.filter(p=>p.followUpDate>=today()).slice(0,6),overdue=scheduled.filter(p=>p.followUpDate<today()).length,max=Math.max(1,revenue,spend,balance);const bars=[{label:'Collected',amount:revenue,tone:'green'},{label:'Expenses',amount:spend,tone:'red'},{label:'Still due',amount:balance,tone:'blue'}];return <section className="content dashboardContent"><div className="stats"><Stat icon={<Users/>} label="Total patients" value={patients.length} tone="blue"/><Stat icon={<CreditCard/>} label="Revenue collected" value={money(revenue)} tone="green"/><Stat icon={<AlertCircle/>} label="Pending balance" value={money(balance)} tone="red"/><Stat icon={<Activity/>} label="Clinic expenses" value={money(spend)} tone="red"/><Stat icon={<CalendarDays/>} label="Upcoming visits" value={upcoming.length} tone="blue"/><Stat icon={<AlertCircle/>} label="Overdue follow-ups" value={overdue} tone={overdue?'red':'green'}/></div><div className="grid2"><div className="card"><div className="cardHead"><div><h3>Recently visited patients</h3><p>Latest visits across your patient records</p></div></div>{recent.length?<div className="table"><div className="tr th"><span>Patient</span><span>Condition</span><span>Visit date</span><span>Status</span></div>{recent.map(p=><button className="tr row" key={p.id} onClick={()=>onOpen(p.id)}><span><b>{p.name}</b><small>{p.id} | {p.age} yrs</small></span><span>{p.condition}</span><span>{p.visitDate}</span><span><Badge status={p.status}/></span></button>)}</div>:<p className="emptyState">No patient visits recorded yet.</p>}</div><div className="card"><div className="cardHead"><div><h3>Upcoming visits</h3><p>Scheduled patient follow-ups{overdue?` · ${overdue} overdue`:''}</p></div><CalendarDays size={18}/></div><div className="followList">{upcoming.length?upcoming.map(p=><button key={p.id} onClick={()=>onOpen(p.id)} className="follow" title={`View ${p.name}'s patient record`}><div className="dateBox"><b>{new Date(p.followUpDate+'T00:00:00').getDate()}</b><span>{new Date(p.followUpDate+'T00:00:00').toLocaleString('en',{month:'short'})}</span></div><div><b>{p.name}</b><span>{p.condition} · {p.followUpDate}{p.followUpTime?` at ${p.followUpTime}`:''}</span></div><span className="arrow visitActionLabel"><Eye size={15}/><span>View patient</span></span></button>):<p className="emptyState">No upcoming visits scheduled.</p>}{overdue>0&&<button className="linkBtn" onClick={()=>onOpen(scheduled.find(p=>p.followUpDate<today())!.id)}>Review overdue follow-ups ({overdue})</button>}</div></div></div><div className="card financeChart"><div className="cardHead"><div><h3>Clinic cash flow</h3><p>Collected revenue, expenses and outstanding patient balances</p></div><BarChart3 size={18}/></div><div className="financeBars">{bars.map(b=><div className="financeBar" key={b.label}><div className="financeBarMeta"><span>{b.label}</span><b>{money(b.amount)}</b></div><div className="financeTrack"><i className={b.tone} style={{width:`${Math.max(b.amount>0?3:0,b.amount/max*100)}%`}}/></div></div>)}</div></div></section>}function Stat({icon,label,value,tone}:{icon:React.ReactNode;label:string;value:number|string;tone:string}){return <div className="stat"><div className={'statIcon '+tone}>{icon}</div><div><span>{label}</span><strong>{value}</strong></div></div>}
function Badge({status}:{status:string}){return <span className={'badge '+status.toLowerCase().replace('-','')}>{status}</span>}
function Patients({patients,search,onOpen,onNew,update,onDelete}:{patients:Patient[];search:string;onOpen:(id:string)=>void;onNew:()=>void;update:(p:Patient)=>void;onDelete:(id:string)=>void}){const [editing,setEditing]=useState<Patient|null>(null);const list=patients.filter(p=>(p.name+' '+p.id+' '+p.condition+' '+p.phone+' '+(p.email||'')).toLowerCase().includes(search.toLowerCase()));const save=()=>{if(editing)update(editing);setEditing(null)};return <section className="content"><div className="pageTitle"><div><span className="eyebrow">PATIENT CRM</span><h2>Patients</h2><p>{patients.length} patient records</p></div><button className="primary" onClick={onNew}><Plus size={17}/> Add patient</button></div><div className="card patientCard"><div className="table wide patientDirectory"><div className="tr th"><span>Patient</span><span>Phone</span><span>Events</span><span>Patient status</span><span>Actions</span></div>{list.map(p=><div className="tr row directoryRow" key={p.id}><span className="clientCell"><i>{p.name.trim().split(/\s+/).map(n=>n[0]).join('').slice(0,1).toUpperCase()}</i><span><b>{p.name}</b><small>{p.email||p.id}</small></span></span><span>{p.phone||'—'}</span><span>{p.visitHistory?.length??(p.visitDate?1:0)}</span><span><Badge status={p.status}/></span><span className="patientActions"><button className="viewAction" title="View patient" onClick={()=>onOpen(p.id)}><Eye size={17}/></button><button className="editAction" title="Edit patient" onClick={()=>setEditing(p)}><Pencil size={16}/></button><button className="deleteAction" title="Delete patient" onClick={()=>{if(window.confirm(`Delete ${p.name} and their patient record?`))onDelete(p.id)}}><Trash2 size={17}/></button></span></div>)}{list.length===0&&<p className="emptyState">No patients match your search.</p>}</div></div>{editing&&<div className="modalWrap" onMouseDown={e=>{if(e.target===e.currentTarget)setEditing(null)}}><div className="modal directoryEditModal"><div className="modalHead"><div><h3>Edit patient</h3><p>Update the patient's information.</p></div><button className="close" onClick={()=>setEditing(null)}><X/></button></div><EditPatient p={editing} setP={setEditing} save={save} cancel={()=>setEditing(null)}/></div></div>}</section>}function FollowUps({patients,update,onOpen,onNew}:{patients:Patient[];update:(p:Patient)=>void;onOpen:(id:string)=>void;onNew:()=>void}){const [adding,setAdding]=useState(false),[selected,setSelected]=useState(''),[date,setDate]=useState(today()),[time,setTime]=useState('10:00'),[note,setNote]=useState('');const scheduled=patients.filter(p=>p.followUpDate&&p.status!=='Completed').sort((a,b)=>a.followUpDate.localeCompare(b.followUpDate)),late=scheduled.filter(p=>p.followUpDate<today()),next=scheduled.filter(p=>p.followUpDate>=today());const saveVisit=()=>{const p=patients.find(x=>x.id===selected);if(!p||!date)return;update({...p,followUpDate:date,followUpTime:time,followUpNotes:note,status:'Follow-up'});setAdding(false);setSelected('');setNote('')};const markVisited=(p:Patient)=>update({...p,visitDate:today(),visitHistory:Array.from(new Set([...(p.visitHistory||[p.visitDate]),today()])),followUpDate:'',followUpTime:'',status:'Active'});const group=(title:string,items:Patient[],overdue=false)=><div className="card followupCard"><div className="cardHead"><div><h3>{title}</h3><p>{items.length} {items.length===1?'patient':'patients'}</p></div></div>{items.length?items.map(p=><div className="followupRow" key={p.id}><div className={'dateBox '+(overdue?'overdueDate':'')}><b>{new Date(p.followUpDate+'T00:00:00').getDate()}</b><span>{new Date(p.followUpDate+'T00:00:00').toLocaleString('en',{month:'short'})}</span></div><div className="followupInfo"><b>{p.name}</b><span>{p.condition} · {p.phone||'No phone'}</span><small>{overdue?'Overdue since':'Scheduled'} {p.followUpDate}{p.followUpTime?` at ${p.followUpTime}`:''}{p.followUpNotes?` · ${p.followUpNotes}`:''}</small></div><button className="secondary" onClick={()=>onOpen(p.id)}>Open record</button><button className="primary" onClick={()=>markVisited(p)}>Mark visited</button></div>):<p className="emptyState">No patients in this list.</p>}</div>;return <section className="content"><div className="pageTitle"><div><span className="eyebrow">PATIENT CARE</span><h2>Follow-ups</h2><p>Review overdue appointments and manage scheduled patient visits.</p></div><div className="headerBtns"><button className="secondary" onClick={()=>setAdding(true)}><Plus size={16}/> Add existing patient</button><button className="primary" onClick={onNew}><Plus size={16}/> New patient visit</button></div></div><div className="followupGroups">{group('Overdue follow-ups',late,true)}{group('Upcoming visits',next)}</div>{adding&&<div className="modalWrap" onMouseDown={e=>{if(e.target===e.currentTarget)setAdding(false)}}><div className="modal appointmentModal"><div className="modalHead"><div><h3>Schedule a patient visit</h3><p>Select an existing patient and set the appointment.</p></div><button className="close" onClick={()=>setAdding(false)}><X/></button></div><div className="formGrid"><Field label="Patient"><select value={selected} onChange={e=>setSelected(e.target.value)}><option value="">Choose patient</option>{patients.map(p=><option key={p.id} value={p.id}>{p.name} · {p.id}</option>)}</select></Field><Field label="Visit date"><input type="date" min={today()} value={date} onChange={e=>setDate(e.target.value)}/></Field><Field label="Visit time"><input type="time" value={time} onChange={e=>setTime(e.target.value)}/></Field><Field label="Visit note"><input value={note} onChange={e=>setNote(e.target.value)} placeholder="Optional reason or note"/></Field></div><div className="formActions"><button className="secondary" onClick={()=>setAdding(false)}>Cancel</button><button className="primary" disabled={!selected||!date} onClick={saveVisit}>Schedule visit</button></div></div></div>}</section>}function PatientDetail({patient:p,update,back}:{patient:Patient;update:(p:Patient)=>void;back:()=>void}){const [tab,setTab]=useState<'overview'|'plan'|'imaging'|'report'>('overview');const [editing,setEditing]=useState(false); const [draft,setDraft]=useState(p); useEffect(()=>setDraft(p),[p.id,p]); const cancel=()=>{setDraft(p);setEditing(false)},save=()=>{update(draft);setEditing(false)};return <section className="content"><button className="back" onClick={back}><ArrowLeft size={17}/> Patients</button><div className="patientHeader"><div className="patientIdentity"><div className="bigAvatar">{p.name.split(' ').map(x=>x[0]).join('').slice(0,2)}</div><div><div className="nameLine"><h2>{p.name}</h2><Badge status={p.status}/></div><p>{p.id} | {p.age} years | {p.gender} | {p.phone}{p.email?` | ${p.email}`:''}</p><span className="mini">Last visit {p.visitDate}</span></div></div><div className="headerBtns"><button className="secondary" onClick={()=>editing?cancel():setEditing(true)}>{editing?'Cancel':'Edit patient'}</button><button className="primary" onClick={()=>exportPDF(p)}><Download size={17}/> Export PDF</button></div></div><div className="tabs"><button className={tab==='overview'?'sel':''} onClick={()=>setTab('overview')}>Overview</button><button className={tab==='plan'?'sel':''} onClick={()=>setTab('plan')}>Exercise plan</button><button className={tab==='imaging'?'sel':''} onClick={()=>setTab('imaging')}>X-rays</button><button className={tab==='report'?'sel':''} onClick={()=>setTab('report')}>Outcome report</button></div>{editing?<EditPatient p={draft} setP={setDraft} save={save} cancel={cancel}/>:tab==='overview'?<Overview p={p}/>:tab==='plan'?<Plan p={p} update={update}/>:tab==='imaging'?<Imaging p={p} update={update}/>:<Report p={p}/>}</section>}
function Overview({p}:{p:Patient}){const delta=p.painAfter!=null?p.painBefore-p.painAfter:null;return <div className="detailGrid"><div className="detailFinance"><div className="patientFinanceHero"><div><span>Patient payment status</span><b className={((p.fee||0)>0&&(p.paid||0)>=(p.fee||0))?'paidValue':(p.paid||0)>0?'partialValue':'dueValue'}>{(p.fee||0)>0&&(p.paid||0)>=(p.fee||0)?'Fully paid':(p.paid||0)>0?'Partially paid':'Unpaid'}</b></div><span>{p.id} · {p.condition}</span></div><div className="patientFinanceCards"><div><i><IndianRupee/></i><span>Total business<strong>{money(p.fee||0)}</strong></span></div><div><i className="paidIcon"><CheckCircle2/></i><span>Amount paid<strong className="paidValue">{money(p.paid||0)}</strong></span></div><div><i className="dueIcon"><Clock/></i><span>Pending amount<strong className="dueValue">{money(Math.max(0,(p.fee||0)-(p.paid||0)))}</strong></span></div></div></div><div className="card"><div className="cardHead"><div><h3>Clinical snapshot</h3><p>Initial assessment and current outcome</p></div><ClipboardList size={18}/></div><div className="snapshot"><Metric label="Pain score" before={p.painBefore} after={p.painAfter} suffix="/10"/><Metric label="Mobility" text={p.mobilityBefore} afterText={p.mobilityAfter}/><Metric label="Plan duration" text={p.planMonths+' months'}/><Metric label="Follow-up" text={p.followUpDate}/></div></div><div className="card"><div className="cardHead"><div><h3>Patient information</h3><p>Contact and health details</p></div></div><div className="notes"><div><label>Mobile and email</label><b>{p.phone||'—'}{p.email?` · ${p.email}`:''}</b></div><div><label>Height and weight</label><b>{p.height?`${p.height} cm`: 'Height not recorded'} · {p.weight?`${p.weight} kg`:'Weight not recorded'}</b></div><div><label>Emergency contact</label><b>{p.emergencyContact||'Not recorded'}</b></div><div><label>Address</label><b>{p.address||'Not recorded'}</b></div><div><label>Medical history and allergies</label><p>{p.medicalHistory||'No medical history recorded.'}{p.allergies?` Allergies: ${p.allergies}`:''}</p></div><div><label>Diagnosis · {p.doctor}</label><b>{p.diagnosis||p.condition}</b></div></div></div><div className="card visitNotes"><div className="cardHead"><div><h3>Visit notes</h3><p>Clinical observations</p></div><FileText size={17}/></div><p>{p.notes||'No visit notes recorded.'}</p><small>Last visit: {p.visitDate||'Not recorded'}{p.followUpDate&&<> · Next visit {p.followUpDate} {p.followUpTime||''}</>}</small></div><div className="card full"><div className="cardHead"><div><h3>3-month outcome</h3><p>Compare baseline with follow-up measurements</p></div>{delta!=null&&<div className="outcomePill"><CheckCircle2 size={16}/> {delta} point pain reduction</div>}</div><div className="outcome"><div><span>Before treatment</span><strong>{p.painBefore}/10</strong><div className="bar"><i style={{width:(p.painBefore*10)+'%'}}/></div></div><div className="outArrow">to</div><div><span>After treatment</span><strong>{p.painAfter!=null?p.painAfter+'/10':'Not recorded'}</strong><div className="bar green"><i style={{width:((p.painAfter??10)*10)+'%'}}/></div></div></div></div></div>}function Metric({label,before,after,suffix='',text,afterText}:{label:string;before?:number;after?:number;suffix?:string;text?:string;afterText?:string}){return <div className="metric"><span>{label}</span>{before!=null?<div><b>{before}{suffix}</b><em>to</em><strong>{after!=null?after+suffix:'-'}</strong></div>:<div><b>{text}</b>{afterText&&<><em>to</em><strong>{afterText}</strong></>}</div>}</div>}
function Plan({p,update}:{p:Patient;update:(p:Patient)=>void}){const add=()=>update({...p,exercises:[...p.exercises,{name:"New exercise",frequency:"1x daily",duration:"10 reps",notes:""}]});const change=(i:number,k:keyof Exercise,v:string)=>update({...p,exercises:p.exercises.map((e,j)=>j===i?{...e,[k]:v}:e)});return <div className="card"><div className="cardHead"><div><h3>Prescribed exercise plan</h3><p>{p.planMonths}-month plan  |  follow-up {p.followUpDate}</p></div><button className="secondary" onClick={add}><Plus size={16}/> Add exercise</button></div><div className="planDuration"><label>Treatment duration (months)<input type="number" min="1" value={p.planMonths} onChange={e=>update({...p,planMonths:Number(e.target.value)})}/></label></div><div className="exerciseList">{p.exercises.map((e,i)=><div className="exercise editableExercise" key={i}><div className="exerciseNum">{i+1}</div><div className="exerciseMain"><input aria-label="Exercise name" value={e.name} onChange={ev=>change(i,"name",ev.target.value)}/><div className="exerciseFields"><input aria-label="Frequency" value={e.frequency} onChange={ev=>change(i,"frequency",ev.target.value)}/><input aria-label="Duration" value={e.duration} onChange={ev=>change(i,"duration",ev.target.value)}/></div><input aria-label="Instructions" value={e.notes} placeholder="Instructions" onChange={ev=>change(i,"notes",ev.target.value)}/></div><button className="iconBtn removeExercise" aria-label="Remove exercise" onClick={()=>update({...p,exercises:p.exercises.filter((_,j)=>j!==i)})}><Trash2 size={16}/></button></div>)}</div></div>}
function Imaging({p,update}:{p:Patient;update:(p:Patient)=>void}){const upload=(key:'before'|'after',file?:File)=>{if(!file)return;const r=new FileReader();r.onload=()=>update({...p,xray:{...p.xray,[key]:String(r.result)}});r.readAsDataURL(file)};return <div className="card"><div className="cardHead"><div><h3>X-ray comparison</h3><p>Upload baseline and 3-month follow-up images.</p></div><ImagePlus size={18}/></div><div className="xrayGrid"><XrayBox title="Before treatment" image={p.xray.before} onFile={f=>upload('before',f)}/><div className="compareArrow">to</div><XrayBox title="After 3 months" image={p.xray.after} onFile={f=>upload('after',f)}/></div><div className="imageNote"><AlertCircle size={16}/> Store only images and information appropriate for your clinic's privacy, consent and retention requirements.</div></div>}
function XrayBox({title,image,onFile}:{title:string;image?:string;onFile:(f?:File)=>void}){return <div className="xrayBox"><div className="xrayTitle"><b>{title}</b><label className="upload"><ImagePlus size={15}/> Upload<input type="file" accept="image/*" onChange={e=>onFile(e.target.files?.[0])}/></label></div><div className="xrayImage">{image?<img src={image}/>:<div className="emptyImg"><ImagePlus size={30}/><span>No X-ray uploaded</span><small>PNG, JPG or JPEG</small></div>}</div></div>}
function Report({p}:{p:Patient}){return <div className="reportPreview"><div className="reportTop"><div><span className="eyebrow">PATIENT OUTCOME REPORT</span><h3>{p.name}</h3><p>{p.id}  |  {p.condition}</p></div><button className="primary" onClick={()=>exportPDF(p)}><FileText size={17}/> Generate PDF</button></div><div className="reportCards"><Metric label="Pain" before={p.painBefore} after={p.painAfter} suffix="/10"/><Metric label="Mobility" text={p.mobilityBefore} afterText={p.mobilityAfter}/><Metric label="Plan" text={p.planMonths+' months'}/></div><div className="reportX"><div><span>Before</span>{p.xray.before?<img src={p.xray.before}/>:<div className="reportEmpty">No image</div>}</div><div><span>After</span>{p.xray.after?<img src={p.xray.after}/>:<div className="reportEmpty">No image</div>}</div></div><p className="reportFoot">This report summarizes recorded clinical information and patient-reported/clinician-entered outcomes. It is not an automated radiological diagnosis.</p></div>}
function EditPatient({p,setP,save,cancel}:{p:Patient;setP:(p:Patient)=>void;save:()=>void;cancel:()=>void}){const str=(k:keyof Patient)=>(e:React.ChangeEvent<HTMLInputElement|HTMLTextAreaElement|HTMLSelectElement>)=>setP({...p,[k]:e.target.value} as Patient),num=(k:'age'|'height'|'weight'|'painBefore'|'painAfter'|'fee'|'paid'|'planMonths')=>(e:React.ChangeEvent<HTMLInputElement>)=>setP({...p,[k]:e.target.value===''?undefined:Number(e.target.value)} as Patient);return <div className="card form"><h3>Patient and visit information</h3><div className="formGrid"><Field label="Patient name"><input value={p.name} onChange={str('name')}/></Field><Field label="Age"><input type="number" min="0" value={p.age} onChange={num('age')}/></Field><Field label="Gender"><select value={p.gender} onChange={str('gender')}><option value="">Select</option><option>Female</option><option>Male</option><option>Other</option></select></Field><Field label="Mobile number"><input type="tel" value={p.phone} onChange={str('phone')}/></Field><Field label="Email"><input type="email" value={p.email||''} onChange={str('email')}/></Field><Field label="Height (cm)"><input type="number" min="0" step="0.1" value={p.height??''} onChange={num('height')}/></Field><Field label="Weight (kg)"><input type="number" min="0" step="0.1" value={p.weight??''} onChange={num('weight')}/></Field><Field label="Emergency contact"><input value={p.emergencyContact||''} onChange={str('emergencyContact')}/></Field><Field label="Address" full><input value={p.address||''} onChange={str('address')}/></Field><Field label="Condition"><input value={p.condition} onChange={str('condition')}/></Field><Field label="Diagnosis"><input value={p.diagnosis} onChange={str('diagnosis')}/></Field><Field label="Doctor"><input value={p.doctor} onChange={str('doctor')}/></Field><Field label="Mobility before"><input value={p.mobilityBefore} onChange={str('mobilityBefore')}/></Field><Field label="Mobility after"><input value={p.mobilityAfter||''} onChange={str('mobilityAfter')}/></Field><Field label="Treatment duration (months)"><input type="number" min="1" value={p.planMonths} onChange={num('planMonths')}/></Field><Field label="Visit date"><input type="date" value={p.visitDate} onChange={str('visitDate')}/></Field><Field label="Follow-up date"><input type="date" value={p.followUpDate} onChange={str('followUpDate')}/></Field><Field label="Follow-up time"><input type="time" value={p.followUpTime||''} onChange={str('followUpTime')}/></Field><Field label="Follow-up note"><input value={p.followUpNotes||''} onChange={str('followUpNotes')}/></Field><Field label="Patient status"><select value={p.status} onChange={str('status')}><option>Active</option><option>Follow-up</option><option>Completed</option></select></Field><Field label="Medical history"><textarea value={p.medicalHistory||''} onChange={str('medicalHistory')}/></Field><Field label="Allergies"><textarea value={p.allergies||''} onChange={str('allergies')}/></Field><Field label="Pain before (0-10)"><input type="number" min="0" max="10" value={p.painBefore} onChange={num('painBefore')}/></Field><Field label="Pain after (0-10)"><input type="number" min="0" max="10" value={p.painAfter??''} onChange={num('painAfter')}/></Field><Field label="Treatment fee (₹)"><input type="number" min="0" value={p.fee??''} onChange={num('fee')}/></Field><Field label="Amount paid (₹)"><input type="number" min="0" value={p.paid??''} onChange={num('paid')}/></Field><Field label="Clinical notes" full><textarea value={p.notes} onChange={str('notes')}/></Field></div><div className="formActions"><button className="secondary" onClick={cancel}>Cancel</button><button className="primary" onClick={save}><CheckCircle2 size={17}/> Save changes</button></div></div>}function Field({label,children,full}:{label:string;children:React.ReactNode;full?:boolean}){return <label className={full?'field fullField':'field'}><span>{label}</span>{children}</label>}
function NewPatient({onClose,onCreate,scheduleVisit=false}:{onClose:()=>void;onCreate:(p:Patient)=>void;scheduleVisit?:boolean}){const [p,setP]=useState<Patient>({id:'YC-'+(1000+Math.floor(Math.random()*8999)),name:'',age:0,gender:'',phone:'',email:'',visitDate:scheduleVisit?'':today(),condition:'',painBefore:0,mobilityBefore:'Not recorded',notes:'',diagnosis:'',doctor:'Dr. Pradnesh Naikwade',planMonths:3,followUpDate:scheduleVisit?today():new Date(Date.now()+90*86400000).toISOString().slice(0,10),followUpTime:'10:00',status:scheduleVisit?'Follow-up':'Active',visitHistory:scheduleVisit?[]:[today()],xray:{},exercises:[],fee:0,paid:0});return <div className="modalWrap" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><div className="modal"><div className="modalHead"><div><h3>New patient</h3><p>Add contact, health, treatment and payment details.</p></div><button className="close" onClick={onClose}><X/></button></div><div className="formGrid"><Field label="Patient name"><input autoFocus value={p.name} onChange={e=>setP({...p,name:e.target.value})}/></Field><Field label="Age"><input type="number" min="0" value={p.age||''} onChange={e=>setP({...p,age:Number(e.target.value)})}/></Field><Field label="Gender"><select value={p.gender} onChange={e=>setP({...p,gender:e.target.value})}><option value="">Select</option><option>Female</option><option>Male</option><option>Other</option></select></Field><Field label="Mobile number"><input type="tel" value={p.phone} onChange={e=>setP({...p,phone:e.target.value})}/></Field><Field label="Email"><input type="email" value={p.email} onChange={e=>setP({...p,email:e.target.value})}/></Field><Field label="Height (cm)"><input type="number" min="0" step="0.1" value={p.height??''} onChange={e=>setP({...p,height:e.target.value?Number(e.target.value):undefined})}/></Field><Field label="Weight (kg)"><input type="number" min="0" step="0.1" value={p.weight??''} onChange={e=>setP({...p,weight:e.target.value?Number(e.target.value):undefined})}/></Field><Field label="Emergency contact"><input value={p.emergencyContact||''} onChange={e=>setP({...p,emergencyContact:e.target.value})}/></Field><Field label="Address" full><input value={p.address||''} onChange={e=>setP({...p,address:e.target.value})}/></Field><Field label="Condition"><input value={p.condition} onChange={e=>setP({...p,condition:e.target.value})}/></Field><Field label="Diagnosis"><input value={p.diagnosis} onChange={e=>setP({...p,diagnosis:e.target.value})}/></Field><Field label="Medical history"><textarea value={p.medicalHistory||''} onChange={e=>setP({...p,medicalHistory:e.target.value})}/></Field><Field label="Allergies"><textarea value={p.allergies||''} onChange={e=>setP({...p,allergies:e.target.value})}/></Field><Field label="Visit date"><input type="date" value={p.visitDate} onChange={e=>setP({...p,visitDate:e.target.value})}/></Field><Field label="Follow-up date"><input type="date" value={p.followUpDate} onChange={e=>setP({...p,followUpDate:e.target.value})}/></Field><Field label="Follow-up time"><input type="time" value={p.followUpTime||''} onChange={e=>setP({...p,followUpTime:e.target.value})}/></Field><Field label="Treatment fee (₹)"><input type="number" min="0" value={p.fee||''} onChange={e=>setP({...p,fee:Number(e.target.value)})}/></Field><Field label="Amount paid (₹)"><input type="number" min="0" value={p.paid||''} onChange={e=>setP({...p,paid:Number(e.target.value)})}/></Field></div><div className="formActions"><button className="secondary" onClick={onClose}>Cancel</button><button className="primary" disabled={!p.name||!p.condition} onClick={()=>onCreate({...p,paymentStatus:(p.paid||0)<=0?'Pending':(p.fee||0)>0&&(p.paid||0)>=(p.fee||0)?'Done':'Partially paid'})}><Plus size={17}/> Create patient</button></div></div></div>}function exportPDF(p:Patient){const doc=new jsPDF();const blue=[29,99,190] as const;doc.setFont('helvetica','bold');doc.setFontSize(20);doc.setTextColor(...blue);doc.text('YogaCare',20,22);doc.setFontSize(10);doc.setTextColor(90);doc.text('PATIENT OUTCOME REPORT',20,30);doc.setTextColor(30);doc.setFontSize(16);doc.text(p.name,20,43);doc.setFontSize(10);doc.setFont('helvetica','normal');doc.text(`${p.id}  |  ${p.age} years  |  ${p.gender}  |  ${p.condition}`,20,50);doc.line(20,56,190,56);doc.setFont('helvetica','bold');doc.text('Clinical summary',20,68);doc.setFont('helvetica','normal');doc.text(`Diagnosis: ${p.diagnosis||'-'}`,20,76);doc.text(`Doctor: ${p.doctor}`,20,83);doc.text(`Initial pain: ${p.painBefore}/10`,20,90);doc.text(`Follow-up pain: ${p.painAfter!=null?p.painAfter+'/10':'Not recorded'}`,20,97);doc.text(`Mobility: ${p.mobilityBefore}  to  ${p.mobilityAfter||'Not recorded'}`,20,104);doc.text(`Treatment plan: ${p.planMonths} months`,20,111);doc.text(`Follow-up date: ${p.followUpDate}`,20,118);doc.setFont('helvetica','bold');doc.text('Exercise plan',20,132);doc.setFont('helvetica','normal');let y=140;p.exercises.forEach((e,i)=>{doc.text(`${i+1}. ${e.name} - ${e.frequency}, ${e.duration}`,24,y);if(e.notes){doc.setFontSize(9);doc.setTextColor(100);doc.text(e.notes,30,y+5);doc.setFontSize(10);doc.setTextColor(30);y+=10}else y+=7});if(y>205){doc.addPage();y=24}else y=Math.max(y+8,175);doc.setFont('helvetica','bold');doc.text('X-ray comparison',20,y);const addImg=(src:string|undefined,x:number,label:string)=>{doc.setFont('helvetica','normal');doc.text(label,x,y+8);if(src){try{doc.addImage(src,'JPEG',x,y+13,75,58,'xray'+x)}catch{doc.rect(x,y+13,75,58)}}else{doc.rect(x,y+13,75,58);doc.setFontSize(9);doc.text('No image uploaded',x+20,y+43);}};addImg(p.xray.before,20,'Before treatment');addImg(p.xray.after,115,'After 3 months');doc.setFontSize(8);doc.setTextColor(100);doc.text('This report reflects recorded clinical information. It is not an automated radiological diagnosis.',20,285);doc.save(`${p.id}-${p.name.replace(/\s+/g,'-')}-outcome-report.pdf`)}

const money=(n:number)=>'₹'+(n||0).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
function Payments({patients,update,expenses,setExpenses}:{patients:Patient[];update:(p:Patient)=>void;expenses:Expense[];setExpenses:React.Dispatch<React.SetStateAction<Expense[]>>}){const [tab,setTab]=useState<'patients'|'expenses'>('patients'),[entry,setEntry]=useState<{patient:Patient;amount:string;date:string;note:string}|null>(null),[history,setHistory]=useState<string|null>(null);const collected=patients.reduce((s,p)=>s+(p.paid||0),0),billed=patients.reduce((s,p)=>s+(p.fee||0),0),balance=patients.reduce((s,p)=>s+Math.max(0,(p.fee||0)-(p.paid||0)),0);const status=(p:Patient)=>p.fee&&p.paid&&p.paid>=p.fee?'Fully paid':p.paid?'Partially paid':'Unpaid';const add=()=>{if(!entry)return;const p=entry.patient,amount=Number(entry.amount),remaining=Math.max(0,(p.fee||0)-(p.paid||0));if(amount<=0||amount>remaining)return;update({...p,paid:(p.paid||0)+amount,paymentStatus:(p.paid||0)+amount>=(p.fee||0)?'Done':'Partially paid',paymentHistory:[...(p.paymentHistory||[]),{id:uid(),amount,date:entry.date,note:entry.note.trim()||undefined}]});setEntry(null)};return <section className="content"><div className="pageTitle"><div><span className="eyebrow">ACCOUNTS</span><h2>Payments</h2><p>Patient collections, payment history and clinic expenses.</p></div></div><div className="paymentTabs"><button className={tab==='patients'?'selected':''} onClick={()=>setTab('patients')}>Patient payments</button><button className={tab==='expenses'?'selected':''} onClick={()=>setTab('expenses')}>Expenses</button></div>{tab==='expenses'?<Expenses expenses={expenses} setExpenses={setExpenses}/>:<><div className="paymentSummary"><div><i><IndianRupee/></i><span>Total business<strong>{money(billed)}</strong></span></div><div><i className="paidIcon"><CheckCircle2/></i><span>Amount paid<strong className="paidValue">{money(collected)}</strong></span></div><div><i className="dueIcon"><Clock/></i><span>Pending amount<strong className="dueValue">{money(balance)}</strong></span></div></div><div className="card patientCard"><div className="table paymentTable optimizedPayments"><div className="tr th"><span>Patient</span><span>Total fee</span><span>Amount paid</span><span>Pending</span><span>Status / actions</span></div>{patients.map(p=>{const due=Math.max(0,(p.fee||0)-(p.paid||0)),state=status(p);return <React.Fragment key={p.id}><div className="tr row paymentRow"><div className="paymentPatient"><b>{p.name}</b><small>{p.phone||p.id}</small></div><input aria-label={`${p.name} treatment fee`} type="number" min="0" value={p.fee||''} placeholder="Set fee" onChange={e=>update({...p,fee:Number(e.target.value)})}/><b className="paidValue">{money(p.paid||0)}</b><b className="dueValue">{money(due)}</b><span className="paymentActions"><span className={'payBadge '+state.toLowerCase().replace(' ','')}>{state}</span>{due>0&&<button className="secondary addPaymentButton" onClick={()=>setEntry({patient:p,amount:'',date:new Date().toISOString().slice(0,16),note:''})}><Plus size={14}/> Add payment</button>}<button className="historyToggle" onClick={()=>setHistory(history===p.id?null:p.id)}>{history===p.id?'Hide':'History'} ({p.paymentHistory?.length||0})</button></span></div>{history===p.id&&<div className="paymentHistoryRow">{p.paymentHistory?.length?p.paymentHistory.map(x=><div key={x.id}><span>{x.date.replace('T',' ')}</span><b>{money(x.amount)}</b><small>{x.note||'Payment received'}</small></div>):<span>No individual payment entries recorded yet. Previous total paid: {money(p.paid||0)}</span>}</div>}</React.Fragment>})}</div></div></>}{entry&&<div className="modalWrap" onMouseDown={e=>{if(e.target===e.currentTarget)setEntry(null)}}><div className="modal paymentModal"><div className="modalHead"><div><h3>Add payment</h3><p>{entry.patient.name} · Balance due {money(Math.max(0,(entry.patient.fee||0)-(entry.patient.paid||0)))}</p></div><button className="close" onClick={()=>setEntry(null)}><X/></button></div><div className="formGrid"><Field label="Amount received"><input autoFocus type="number" min="0.01" max={Math.max(0,(entry.patient.fee||0)-(entry.patient.paid||0))} value={entry.amount} onChange={e=>setEntry({...entry,amount:e.target.value})}/></Field><Field label="Payment date"><input type="datetime-local" value={entry.date} onChange={e=>setEntry({...entry,date:e.target.value})}/></Field><Field label="Note / method"><input value={entry.note} onChange={e=>setEntry({...entry,note:e.target.value})} placeholder="Cash, UPI, bank transfer…"/></Field></div><div className="formActions"><button className="secondary" onClick={()=>setEntry(null)}>Cancel</button><button className="primary" disabled={!Number(entry.amount)||Number(entry.amount)>Math.max(0,(entry.patient.fee||0)-(entry.patient.paid||0))} onClick={add}>Record payment</button></div></div></div>}</section>}function Expenses({expenses,setExpenses}:{expenses:Expense[];setExpenses:React.Dispatch<React.SetStateAction<Expense[]>>}){const [query,setQuery]=useState(''),[typeFilter,setTypeFilter]=useState('All Types'),[draft,setDraft]=useState<Expense|null>(null);const total=expenses.reduce((s,e)=>s+e.amount,0),types=['All Types',...Array.from(new Set(expenses.map(e=>e.type)))];const shown=[...expenses].filter(e=>(typeFilter==='All Types'||e.type===typeFilter)&&(e.note+' '+e.type).toLowerCase().includes(query.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date));const newExpense=()=>setDraft({id:uid(),type:'Person',note:'',amount:0,date:new Date().toISOString().slice(0,16)});const save=()=>{if(!draft||!draft.note.trim()||draft.amount<=0)return;setExpenses(rows=>rows.some(e=>e.id===draft.id)?rows.map(e=>e.id===draft.id?draft:e):[draft,...rows]);setDraft(null)};return <section className="content expensesPage"><div className="pageTitle"><div><h2>Expenses</h2><p>Track your clinic business expenses</p></div><button className="primary" onClick={newExpense}><Plus size={17}/> Add Expense</button></div><div className="expenseStats"><div className="expenseStat"><div><span>Total Expenses</span><strong className="expenseTotal">{money(total)}</strong></div><i><CreditCard/></i></div><div className="expenseStat"><div><span>Total Entries</span><strong>{expenses.length}</strong></div><i><Activity/></i></div></div><div className="expenseFilters"><div className="expenseSearch"><Search/><input placeholder="Search expenses by note or type..." value={query} onChange={e=>setQuery(e.target.value)}/></div><select value={typeFilter} onChange={e=>setTypeFilter(e.target.value)}>{types.map(t=><option key={t}>{t}</option>)}</select></div><div className="expenseTableWrap"><table className="expenseTable"><thead><tr><th>Type</th><th>Note</th><th>Amount</th><th>Date</th><th>Actions</th></tr></thead><tbody>{shown.map(e=><tr key={e.id}><td><span className="expenseType">{e.type}</span></td><td>{e.note}</td><td className="expenseAmount">{money(e.amount)}</td><td className="expenseDate">{e.date.replace('T',' ')}</td><td><button className="expenseAction edit" title="Edit expense" onClick={()=>setDraft({...e})}>✎</button><button className="expenseAction delete" title="Delete expense" onClick={()=>setExpenses(rows=>rows.filter(x=>x.id!==e.id))}><Trash2 size={17}/></button></td></tr>)}</tbody></table>{shown.length===0&&<p className="emptyState">No expenses found. Add an expense to get started.</p>}</div>{draft&&<div className="modalWrap" onMouseDown={e=>{if(e.target===e.currentTarget)setDraft(null)}}><div className="modal expenseModal"><div className="modalHead"><h3>{expenses.some(e=>e.id===draft.id)?'Edit Expense':'Add Expense'}</h3><button className="close" onClick={()=>setDraft(null)}><X/></button></div><div className="expenseForm"><Field label="Type"><select value={draft.type} onChange={e=>setDraft({...draft,type:e.target.value})}><option>Person</option><option>Supplies</option><option>Rent</option><option>Utilities</option><option>Equipment</option><option>Travel</option><option>Other</option></select></Field><Field label="Note"><input autoFocus value={draft.note} onChange={e=>setDraft({...draft,note:e.target.value})}/></Field><Field label="Amount"><input type="number" min="0.01" step="0.01" value={draft.amount||''} onChange={e=>setDraft({...draft,amount:Number(e.target.value)})}/></Field><Field label="Date"><input type="datetime-local" value={draft.date} onChange={e=>setDraft({...draft,date:e.target.value})}/></Field><p className="expenseHint">Defaulted to the current date and time.</p></div><div className="formActions"><button className="secondary" onClick={()=>setDraft(null)}>Cancel</button><button className="primary" disabled={!draft.note.trim()||draft.amount<=0} onClick={save}>Save Changes</button></div></div></div>}</section>}function Reports({patients,expenses}:{patients:Patient[];expenses:Expense[]}){const [range,setRange]=useState<'Weekly'|'Monthly'|'Yearly'>('Monthly');const records=patients.filter(p=>p.painAfter!=null);const points=range==='Weekly'?['Mon','Tue','Wed','Thu','Fri','Sat','Sun']:range==='Yearly'?['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec']:['Week 1','Week 2','Week 3','Week 4'];const vals=points.map((_,i)=>{const d=range==='Weekly'?new Date(Date.now()-(6-i)*86400000):range==='Yearly'?new Date(new Date().getFullYear(),i,1):new Date(Date.now()-(3-i)*7*86400000);const a=records.filter(p=>{const v=new Date(p.visitDate);return range==='Weekly'?v.toDateString()===d.toDateString():range==='Yearly'?v.getFullYear()===d.getFullYear()&&v.getMonth()===d.getMonth():v>=new Date(d.getTime()-6*86400000)&&v<=d});return a.length?a.reduce((s,p)=>s+(p.painAfter||0),0)/a.length:0});const max=Math.max(10,...vals),coords=vals.map((v,i)=>`${24+i*552/Math.max(1,vals.length-1)},${190-v/max*155}`).join(' ');return <section className="content"><div className="pageTitle"><div><span className="eyebrow">CLINIC REPORTS</span><h2>Reports</h2><p>Track patient outcomes, collections, expenses and clinic performance.</p></div><select className="rangeSelect" value={range} onChange={e=>setRange(e.target.value as typeof range)}><option>Weekly</option><option>Monthly</option><option>Yearly</option></select></div><div className="reportFinance"><div><span>Total billed</span><strong>{money(patients.reduce((s,p)=>s+(p.fee||0),0))}</strong></div><div><span>Revenue collected</span><strong className="paidValue">{money(patients.reduce((s,p)=>s+(p.paid||0),0))}</strong></div><div><span>Pending payments</span><strong className="dueValue">{money(patients.reduce((s,p)=>s+Math.max(0,(p.fee||0)-(p.paid||0)),0))}</strong></div><div><span>Expenses</span><strong className="dueValue">{money(expenses.reduce((s,e)=>s+e.amount,0))}</strong></div><div><span>Net cash flow</span><strong>{money(patients.reduce((s,p)=>s+(p.paid||0),0)-expenses.reduce((s,e)=>s+e.amount,0))}</strong></div><div><span>Fully paid patients</span><strong>{patients.filter(p=>(p.fee||0)>0&&(p.paid||0)>=(p.fee||0)).length}</strong></div><div><span>Partially paid patients</span><strong>{patients.filter(p=>(p.paid||0)>0&&(p.paid||0)<(p.fee||0)).length}</strong></div><div><span>Upcoming follow-ups</span><strong>{patients.filter(p=>p.followUpDate>=today()&&p.status!=='Completed').length}</strong></div></div><div className="card chartCard"><div className="cardHead"><div><h3>Average follow-up pain trend</h3><p>Lower scores indicate less reported pain  |  0-10 scale</p></div><span className="chartLegend"><i/> Average pain</span></div><svg className="trendChart" viewBox="0 0 600 230" role="img" aria-label={`${range} average pain trend`}>{[0,1,2,3,4].map(i=><g key={i}><line x1="24" x2="576" y1={35+i*39} y2={35+i*39} className="gridLine"/><text x="4" y={39+i*39} className="axisLabel">{Math.round(max*(4-i)/4)}</text></g>)}{vals.some(v=>v>0)&&<><polyline points={coords} className="chartLine"/>{coords.split(' ').map((pt,i)=>{const[cx,cy]=pt.split(',');return <circle key={i} cx={cx} cy={cy} r="4" className="chartDot"><title>{points[i]}: {vals[i].toFixed(1)}</title></circle>})}</>}</svg>{!records.length&&<div className="chartEmpty">Follow-up pain scores will appear here when recorded.</div>}</div><div className="card outcomesSummary"><h3>Recorded outcomes</h3><p>{records.length} of {patients.length} patients have follow-up pain scores. Average reduction: {records.length?(records.reduce((s,p)=>s+p.painBefore-(p.painAfter||0),0)/records.length).toFixed(1):'-'} points.</p></div></section>}
function SettingsPage({patients,setPatients}:{patients:Patient[];setPatients:(p:Patient[])=>void}){const [message,setMessage]=useState('');const backup=()=>{const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),patients},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`yogacare-backup-${today()}.json`;a.click();URL.revokeObjectURL(a.href);setMessage('Database backup downloaded.')};const restore=(f?:File)=>{if(!f)return;const r=new FileReader();r.onload=()=>{try{const data=JSON.parse(String(r.result)),rows=Array.isArray(data)?data:data.patients;if(!Array.isArray(rows))throw Error();setPatients(rows);setMessage(`Restored ${rows.length} patient records.`)}catch{setMessage('Invalid YogaCare backup file.')}};r.readAsText(f)};return <section className="content"><div className="pageTitle"><div><span className="eyebrow">PREFERENCES</span><h2>Settings</h2><p>Manage clinic data and appearance.</p></div></div><div className="settingsGrid"><div className="card"><div className="cardHead"><div><h3>Database backup</h3><p>Export or restore patient records, exercise plans and X-rays.</p></div><Download size={19}/></div><div className="settingsActions"><button className="primary" onClick={backup}><Download size={16}/> Download backup</button><label className="secondary restoreButton">Restore backup<input type="file" accept="application/json,.json" onChange={e=>restore(e.target.files?.[0])}/></label></div>{message&&<p className="settingsMessage">{message}</p>}<small className="settingsHint">Backup files contain sensitive patient data. Store them securely.</small></div><div className="card"><div className="cardHead"><div><h3>Appearance</h3><p>Current theme preference.</p></div></div><p className="settingsHint">Doctor name: <b>Dr. Pradnesh Naikwade</b></p><p className="settingsHint">Use the sun/moon button in the top bar to switch theme.</p></div></div></section>}
createRoot(document.getElementById('root')!).render(<App/>);






